# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together (body {claimIds, user}).
# Each selected claim that can be opened (a DRAFT on the sheet, not dated in a closed period) is
# opened and numbered in list order — people in the order they were added, a person's claims
# newest first — and recorded as CLAIM_OPENED, as a single open is; each that cannot is refused and
# left as it is. Answers {opened, refused}. Refused (400) only when no claim is selected.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateBulkOpen {
    public void validate(@RequestBody BulkOpenRequest request, Out<BulkOpenInput> body) throws InvalidSheetException {
        if (request == null || request.claimIds() == null || request.claimIds().isEmpty()) {
            throw new InvalidSheetException("Select the claims to open");
        }
        Set<String> seen = new LinkedHashSet<>();
        List<Long> ids = new ArrayList<>();
        for (String raw : request.claimIds()) {
            String id = raw == null ? "" : raw.trim();
            if (!seen.add(id)) {
                continue;
            }
            Long parsed = null;
            try {
                parsed = Long.parseLong(id);
            } catch (NumberFormatException e) {
                // not an id: no such claim, refused
            }
            ids.add(parsed);
        }
        body.set(new BulkOpenInput(ids, request.user()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order: its people in the order they were
 *  added, a person's claims newest first. Each is opened as a single open would be (its next
 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures.
 *  A claim that is not on the sheet, is not a DRAFT, or is dated in a closed period is refused and
 *  left as it is. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, ClaimLogStore log, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        Map<Long, Person> persons = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
            persons.put(person.getId(), person);
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        int opened = 0;
        for (Claim claim : selected) {
            if (claim.getStatus() != ClaimStatus.DRAFT || closed(periods, claim)) {
                refused++;
                continue;
            }
            Rollup before = rollups.snapshot(sheet);
            if (!store.move(claim, claim.getStatus(), ClaimStatus.OPEN)) {
                refused++;
                continue;
            }
            claim.setStatus(ClaimStatus.OPEN);
            claim.setNumber(Numbering.next(sheet, claim.getDate(), store, settings, sheets, periods));
            claim.setOpenedBy(input.user());
            store.save(claim);
            log.record(claim, input.user());
            Person person = persons.get(claim.getPersonId());
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(ClaimStatus.OPEN.event() + " sheet=" + sheet + " by=" + input.user() + " person="
                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
                    + " number=" + claim.getNumber());
            rollups.record(sheet, input.user(), before);
            opened++;
        }
        result.set(new BulkOpenResult(opened, refused));
    }

    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), claim.getDate());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkOpen {
    public void respond(@Val BulkOpenResult result, ObjectResponse<BulkOpenResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims a bulk open opened, and how many it refused. */
public record BulkOpenResult(int opened, int refused) {
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { claimsKey, useSelectedClaims } from './claims';

type BulkOpenResult = { opened: number; refused: number };

// Opens the selected claims together: the server opens and numbers each that can be opened in list
// order and refuses the rest, and the counts show once it answers (gone while it runs).
function BulkOpen() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [selected, setSelected] = useSelectedClaims();
  const queryClient = useQueryClient();

  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<BulkOpenResult>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-open`, {
        claimIds: claimIds.map(String),
        user,
      }),
    onSuccess: async () => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const submit = useSubmitOnce(bulk);

  return (
    <p>
      <button type="button" data-testid="bulk-open" disabled={bulk.isPending} onClick={() => submit(selected)}>
        Open selected
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
        </>
      )}
      {bulk.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}
          {bulk.error instanceof HttpError && bulk.error.reason ? `${bulk.error.reason}.` : 'The bulk open was refused.'}
        </span>
      )}
    </p>
  );
}

export const contribution = HomeMain.fill({ order: 22, Component: BulkOpen });
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The rule a retirement sets: no claim of a retired person dated after the date they are retired from. */
public final class Retirement {
    private Retirement() {
    }

    public static void refuseClaimDate(Person person, LocalDate date) throws InvalidSheetException {
        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
            throw new InvalidSheetException(person.getName() + " is retired from " + person.getRetiredFrom());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim dated inside a closed period: editing it or moving it on. */
public class CheckClaimPeriod {
    public void check(@Val Claim claim, PeriodStore periods) throws InvalidSheetException {
        refuseClosed(periods, claim.getSheetId(), claim.getDate());
    }

    static void refuseClosed(PeriodStore periods, String sheetId, LocalDate date) throws InvalidSheetException {
        PeriodResponse closed = periods.closedOn(sheetId, date);
        if (closed != null) {
            throw new InvalidSheetException("The period " + closed.name() + " is closed");
        }
    }
}

