import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds each pasted claim in order as the claim form would, a DRAFT recorded as CLAIM_ADDED. */
public class SavePasted {
    public void save(@PathVariable("sheetId") String sheetId, @Val List<PastedClaim> pasted, ClaimStore store,
            SettingStore settings, ClaimLogStore log, RollupService rollups, Audit audit, Out<PasteResult> result) {
        for (PastedClaim p : pasted) {
            var before = rollups.snapshot(sheetId.trim());
            var claim = SaveClaimAdded.add(p.claim(), p.person(), store, settings, log);
            AuditClaimAdded.record(p.claim(), p.person(), claim, before, audit, rollups);
        }
        result.set(new PasteResult(pasted.size()));
    }
}
